/* Turns compact manifest entries (generated by `npm run images`) into the
   object shape <Picture> expects. URLs follow /img/<id>-<width>.<format>. */
import manifest from "../content/image-manifest.json";

const MANIFEST = manifest.images;

/**
 * getImage("h2", { position: "60% 50%" })
 * → { src, width, height, sources: { avif }, placeholder, color, position }
 * Unknown ids return null (and warn in development).
 */
export function getImage(id, extra = {}) {
  const e = MANIFEST[id];
  if (!e) {
    if (import.meta.env.DEV) console.warn(`[images] unknown image id "${id}" — run "npm run images"?`);
    return null;
  }
  const q = e.v ? `?v=${e.v}` : "";
  const srcset = (fmt) => e.widths.map((w) => `/img/${id}-${w}.${fmt}${q} ${w}w`).join(", ");
  return {
    id,
    src: `/img/${id}-${e.fallback}.jpg${q}`,
    width: e.w,
    height: e.h,
    sources: Object.fromEntries((e.formats ?? ["avif"]).map((fmt) => [fmt, srcset(fmt)])),
    placeholder: e.ph,
    color: e.color,
    largest: `/img/${id}-${e.widths[e.widths.length - 1]}.${(e.formats ?? ["avif"])[0]}${q}`,
    ...extra,
  };
}

export const hasImage = (id) => id in MANIFEST;

/** All manifest ids from photos/<category>/ — used to auto-include new photos. */
export function imagesInCategory(category) {
  return Object.keys(MANIFEST).filter((id) => MANIFEST[id].category === category);
}

/** "portrait" | "landscape" | "square" */
export function orientation(img) {
  if (!img) return "landscape";
  const r = img.width / img.height;
  return r > 1.15 ? "landscape" : r < 0.87 ? "portrait" : "square";
}
